'use client';
import { useState, useEffect } from 'react';
import { Contest } from '@/lib/contests';
import { Calendar, Clock, ExternalLink, Filter } from 'lucide-react';
import { cn } from '@/lib/utils';
import { motion, AnimatePresence } from 'framer-motion';

export function ContestList({ initialContests }: { initialContests: Contest[] }) {
    const [filter, setFilter] = useState<string>('All');
    const [contests, setContests] = useState(initialContests);
    const [now, setNow] = useState(new Date());

    useEffect(() => {
        // Hydration helper: Client Side Fetch to bypass potential server-side blocks
        async function refreshData() {
            try {
                const res = await fetch('https://kontests.net/api/v1/all');
                if (res.ok) {
                    const data: Contest[] = await res.json();

                    const upcoming = data
                        .filter(c => ['Codeforces', 'LeetCode', 'AtCoder', 'CodeChef'].includes(c.site))
                        .filter(c => new Date(c.end_time) > new Date())
                        .sort((a, b) => new Date(a.start_time).getTime() - new Date(b.start_time).getTime());

                    if (upcoming.length > 0) {
                        setContests(upcoming);
                    }
                }
            } catch (e) {
                // Silently fail on client too, sticky to server props
            }
        }
        refreshData();

        const timer = setInterval(() => setNow(new Date()), 60000); // Update every minute
        return () => clearInterval(timer);
    }, []);

    const filtered = filter === 'All'
        ? contests
        : contests.filter(c => c.site === filter);

    const platforms = ['All', 'Codeforces', 'LeetCode', 'AtCoder', 'CodeChef'];

    return (
        <div className="space-y-6">
            {/* Filters */}
            <div className="flex flex-wrap items-center gap-2 pb-4 border-b border-zinc-800">
                <div className="flex items-center gap-2 text-zinc-500 text-sm font-medium mr-4">
                    <Filter size={16} /> Filters:
                </div>
                {platforms.map(p => (
                    <button
                        key={p}
                        onClick={() => setFilter(p)}
                        className={cn(
                            "px-4 py-1.5 rounded-full text-xs font-bold transition border",
                            filter === p
                                ? getPlatformStyle(p)
                                : "bg-zinc-900 border-zinc-800 text-zinc-500 hover:text-zinc-300"
                        )}
                    >
                        {p}
                    </button>
                ))}
            </div>

            {/* Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                <AnimatePresence mode="popLayout">
                    {filtered.map((contest, i) => (
                        <motion.div
                            key={contest.name + i}
                            layout
                            initial={{ opacity: 0, scale: 0.95 }}
                            animate={{ opacity: 1, scale: 1 }}
                            exit={{ opacity: 0, scale: 0.95 }}
                            className={cn(
                                "group relative bg-zinc-900/40 p-5 rounded-xl border transition-all hover:-translate-y-1 hover:shadow-xl overflow-hidden",
                                getBorderColor(contest.site)
                            )}
                        >
                            {/* Status Badge */}
                            <div className="absolute top-3 right-3">
                                <StatusBadge start={contest.start_time} end={contest.end_time} />
                            </div>

                            {/* Site Icon/Name */}
                            <div className="flex items-center gap-2 mb-3">
                                <span className={cn("text-xs font-black uppercase tracking-wider px-2 py-0.5 rounded", getTagStyle(contest.site))}>
                                    {contest.site}
                                </span>
                            </div>

                            {/* Title */}
                            <h3 className="text-lg font-bold text-white mb-4 line-clamp-2 min-h-[3.5rem]" title={contest.name}>
                                {contest.name}
                            </h3>

                            {/* Details */}
                            <div className="space-y-3 text-sm text-zinc-400">
                                <div className="flex items-center gap-2">
                                    <Calendar size={14} className="text-zinc-500" />
                                    <span>{formatDate(contest.start_time)}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <Clock size={14} className="text-zinc-500" />
                                    <span>{getDuration(contest.duration)}</span>
                                </div>
                            </div>

                            {/* Actions */}
                            <div className="mt-5 flex items-center gap-3">
                                <a
                                    href={contest.url}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="flex-1 flex items-center justify-center gap-2 bg-white text-black py-2 rounded-lg font-bold text-sm hover:bg-zinc-200 transition"
                                >
                                    Register <ExternalLink size={14} />
                                </a>
                                <a
                                    href={getGoogleCalendarUrl(contest)}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="px-3 py-2 bg-zinc-800 text-zinc-400 rounded-lg hover:text-white hover:bg-zinc-700 transition"
                                    title="Add to Google Calendar"
                                >
                                    <Calendar size={16} />
                                </a>
                            </div>
                        </motion.div>
                    ))}
                </AnimatePresence>

                {filtered.length === 0 && (
                    <div className="col-span-full py-20 text-center text-zinc-500">
                        No upcoming contests found for this filter.
                    </div>
                )}
            </div>
        </div>
    );
}

function StatusBadge({ start, end }: { start: string, end: string }) {
    const now = new Date();
    const startDate = new Date(start);
    const endDate = new Date(end);

    if (now > startDate && now < endDate) {
        return <span className="bg-red-500 text-white text-[10px] font-bold px-2 py-1 rounded-full animate-pulse">LIVE</span>
    }

    const diff = startDate.getTime() - now.getTime();
    const hours = Math.floor(diff / (1000 * 60 * 60));

    if (hours < 24) {
        return <span className="bg-green-500/10 text-green-400 border border-green-500/20 text-[10px] font-bold px-2 py-1 rounded-full">In {hours}h</span>
    }

    const days = Math.floor(hours / 24);
    return <span className="bg-zinc-800 text-zinc-400 text-[10px] font-bold px-2 py-1 rounded-full">In {days}d</span>
}


// Helpers
function getPlatformStyle(site: string) {
    switch (site) {
        case 'Codeforces': return "bg-blue-600 border-blue-500 text-white";
        case 'LeetCode': return "bg-orange-600 border-orange-500 text-white";
        case 'CodeChef': return "bg-amber-800 border-amber-700 text-white";
        case 'AtCoder': return "bg-zinc-100 border-zinc-200 text-black";
        default: return "bg-primary text-primary-foreground";
    }
}

function getTagStyle(site: string) {
    switch (site) {
        case 'Codeforces': return "bg-blue-500/20 text-blue-300";
        case 'LeetCode': return "bg-orange-500/20 text-orange-300";
        case 'CodeChef': return "bg-amber-900/50 text-amber-500";
        case 'AtCoder': return "bg-zinc-800 text-zinc-300 border border-zinc-700";
        default: return "bg-zinc-800 text-zinc-400";
    }
}

function getBorderColor(site: string) {
    switch (site) {
        case 'Codeforces': return "border-blue-500/20 hover:border-blue-500/50";
        case 'LeetCode': return "border-orange-500/20 hover:border-orange-500/50";
        case 'CodeChef': return "border-amber-900/50 hover:border-amber-700/50";
        case 'AtCoder': return "border-zinc-700 hover:border-white/50";
        default: return "border-zinc-800";
    }
}

function formatDate(dateStr: string) {
    const d = new Date(dateStr);
    return d.toLocaleDateString("en-US", { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
}

function getDuration(secondsStr: string) {
    const sec = parseInt(secondsStr);
    const hours = Math.floor(sec / 3600);
    const mins = Math.floor((sec % 3600) / 60);
    return `${hours}h ${mins > 0 ? mins + 'm' : ''}`;
}

function getGoogleCalendarUrl(c: Contest) {
    const start = new Date(c.start_time).toISOString().replace(/-|:|\.\d\d\d/g, "");
    const end = new Date(c.end_time).toISOString().replace(/-|:|\.\d\d\d/g, "");
    const title = encodeURIComponent(c.name);
    const details = encodeURIComponent(`Register here: ${c.url}`);

    return `https://www.google.com/calendar/render?action=TEMPLATE&text=${title}&dates=${start}/${end}&details=${details}&sprop=&sprop=name:`;
}
